local({
  other_text <- if_else(as.integer(ALL_Ethnicity) == 38L, toupper(trimws(ALL_Ethnicity_OtherInput)), NA_character_)
  case_when(
    as.integer(Hispanic) == 1L & as.integer(SITE_ID) %in% c(1L, 10L) ~ "Hispanic",
    .default = coalesce(
      lookup_values(other_text, lookup_ethnicity_other),
      lookup_values(
        haven::as_factor(ALL_Ethnicity),
        lookup_ethnicity,
        dataset_id = spec$dataset_id,
        target_variable = "ethnicity"
      ),
      "Unknown"
    )
  )
})

local({
  ridit <- stats::ave(as.numeric(inclevel), as.integer(SITE_ID), FUN = function(x) {
    r <- (rank(x, na.last = "keep") - 0.5) / sum(!is.na(x))
    if (!any(r >= 0.4 & r <= 0.6, na.rm = TRUE)) {
      r[r %in% r[which.min(abs(r - 0.5))]] <- 0.5
    }
    r
  })
  case_when(is.na(ridit) ~ "Unknown", ridit < 0.4 ~ "Low", ridit <= 0.6 ~ "Medium", .default = "High")
})
